head.b:skin:
/* ===== Theme: Materi Kita v5 ===== */
*,::before,::after{box-sizing:border-box}
body{margin:0;font-family:'Poppins',sans-serif;color:#fff;min-height:100vh;
  background:radial-gradient(circle at center,#e00534 10%,#0d0d0d 90%) fixed}
a{text-decoration:none;color:inherit}
p{margin:0}
.wrap{max-width:1180px;margin:0 auto;padding:0 20px}

/* header */
.site-header{padding:26px 0 8px;text-align:center}
.site-header h1{margin:0;font-size:32px;font-weight:800;letter-spacing:1px;text-transform:uppercase}
.site-header p{opacity:.8;font-size:14px;margin-top:6px}
.nav ul{list-style:none;margin:14px 0 0;padding:0;display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
.nav li a{display:block;padding:6px 18px;border-radius:50px;background:rgba(255,255,255,.12);font-size:14px;transition:.25s}
.nav li a:hover{background:#fff;color:#971C35}
.nav h3,.kategori h3{display:none}
.search{display:flex;justify-content:center;margin:16px 0 0}
.search input{width:min(420px,90%);padding:10px 20px;border:0;border-radius:50px 0 0 50px;font:inherit;font-size:14px;outline:0}
.search button{padding:10px 22px;border:0;border-radius:0 50px 50px 0;background:#0d0d0d;color:#fff;font:inherit;font-size:14px;cursor:pointer}
.kategori ul{list-style:none;margin:14px 0 0;padding:0;display:flex;gap:8px;justify-content:center;flex-wrap:wrap}
.kategori li a{display:block;padding:5px 16px;border-radius:50px;background:rgba(255,255,255,.12);font-size:13px;transition:.25s}
.kategori li a:hover{background:#fff;color:#971C35}
.label-count{display:none}

/* hero */
.hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:20px;padding-top:30px;padding-bottom:10px}
.hero h2{font-size:38px;line-height:1.2;margin:0 0 12px;font-weight:800}
.hero p{opacity:.85;margin-bottom:20px;font-size:15px}
.hero-art{position:relative;height:270px}
.hero-art img{position:absolute;width:200px;height:145px;object-fit:cover;border-radius:18px;
  box-shadow:0 12px 30px rgba(0,0,0,.45);animation:bob 4s ease-in-out infinite}
.hero-art img:nth-child(1){left:2%;top:50px;--r:-12deg}
.hero-art img:nth-child(2){left:30%;top:0;--r:6deg;animation-delay:-1.3s}
.hero-art img:nth-child(3){left:52%;top:90px;--r:-5deg;animation-delay:-2.6s}
@keyframes bob{0%,100%{transform:translateY(0) rotate(var(--r))}50%{transform:translateY(-14px) rotate(var(--r))}}

/* layout utama + sidebar */
.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:30px;align-items:start}
.sidebar{padding-top:30px}
.sidebar .widget{background:rgba(255,255,255,.1);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.12);
  border-radius:20px;padding:18px;margin-bottom:20px;font-size:14px}
.sidebar h3{margin:0 0 12px;font-size:15px;text-transform:uppercase;letter-spacing:.5px}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar li{margin-bottom:10px}
.sidebar .widget-content p{line-height:1.6;opacity:.92}
.PopularPosts li{display:flex;gap:10px;align-items:center}
.PopularPosts .item-thumbnail{float:none;margin:0}
.PopularPosts img{width:56px;height:56px;border-radius:12px;object-fit:cover;display:block}
.PopularPosts .item-title a{font-weight:600;font-size:13px}
.sidebar .btn-wa{margin-top:6px;padding:8px 22px;font-size:13px}

/* grid kartu */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:110px 20px;justify-items:center;padding:110px 0 50px}
.card{width:220px;height:300px;background:#fff;border-radius:20px;position:relative;padding:10px;color:#fff;
  box-shadow:0 4px 20px rgba(50,50,50,.3),0 6px 12px rgba(0,0,0,.15);cursor:pointer}
.card-img{position:absolute;width:200px;height:150px;transition:.5s}
.card-img img{width:100%;height:100%;object-fit:cover;border-radius:14px;transform:scale(1.05)}
.card-data{transform:translateY(168px);text-align:center;transition:.5s}
.card-title{font-size:16px;font-weight:800;color:#971C35;margin-bottom:10px;text-transform:uppercase;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:.5s}
.card-price{font-size:17px;font-weight:800;color:#000;transition:.5s}
.card-description{font-size:13px;font-weight:600;color:#971C35;text-align:left;display:none;
  -webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.card-button{display:block;width:150px;padding:6px 10px;margin:0 auto;background:linear-gradient(135deg,#e00534,#0d0d0d);
  color:#fff;border-radius:50px;font-weight:500;font-size:14px;opacity:0;transition:.25s;
  box-shadow:0 4px 20px rgba(50,50,50,.3),0 6px 12px rgba(0,0,0,.15)}
.card:hover .card-img,.card.active .card-img{transform:translate(-20px,-90px) rotate(-20deg);filter:drop-shadow(0 5px 10px rgba(0,0,0,.5))}
.card:hover .card-data,.card.active .card-data{transform:translateY(76.8px)}
.card:hover .card-title,.card.active .card-title{transform:translateX(-21px);margin-bottom:0}
.card:hover .card-price,.card.active .card-price{transform:translateX(-25px);text-align:start;padding:10px 0 0 30px}
.card:hover .card-description,.card.active .card-description{display:-webkit-box;padding:10px 0 0 8px;margin-bottom:14px}
.card:hover .card-button,.card.active .card-button{opacity:1}
.demo-note{grid-column:1/-1;text-align:center;font-size:13px;opacity:.85;background:rgba(255,255,255,.12);
  border-radius:12px;padding:10px 14px;margin-bottom:-60px}

.sec-title{font-size:22px;font-weight:800;margin:10px 0 0}
.cat-grid{padding-top:90px}
.kosong{grid-column:1/-1;text-align:center;opacity:.85}
/* halaman materi */
.post-page{background:#fff;color:#222;border-radius:20px;padding:28px;margin:30px 0 50px;box-shadow:0 6px 24px rgba(0,0,0,.35)}
.post-page h1{color:#971C35;margin-top:0;text-transform:uppercase}
.post-page img{max-width:100%;height:auto;border-radius:14px}
.btn-wa{display:inline-block;margin-top:16px;padding:10px 28px;border-radius:50px;color:#fff;font-weight:600;
  background:linear-gradient(135deg,#e00534,#0d0d0d)}
.hero .btn-wa{border:2px solid rgba(255,255,255,.4)}
.pager{display:flex;justify-content:space-between;padding-bottom:40px}
.pager a{padding:8px 22px;border-radius:50px;background:rgba(255,255,255,.15)}
footer{text-align:center;padding:30px 0;font-size:13px;opacity:.7}
.blog-feeds,.post-feeds{display:none}

@media(max-width:900px){
  .layout{grid-template-columns:1fr}
  .hero{grid-template-columns:1fr;text-align:center}
  .hero-art{height:230px;max-width:460px;margin:0 auto;width:100%}
  .hero h2{font-size:28px}
}

body.script:
//
(function(){
  var WA = '6289606357045'; // nomor WhatsApp (format 62...)

  // ---- Data contoh (hanya tampil bila blog belum punya postingan) ----
  function art(emoji, c1, c2){
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="'+c1+'"/><stop offset="1" stop-color="'+c2+'"/></linearGradient></defs><rect width="400" height="300" fill="url(#g)"/><text x="200" y="195" font-size="130" text-anchor="middle">'+emoji+'</text></svg>';
    return 'data:image/svg+xml,' + encodeURIComponent(svg);
  }
  var demo = [
    {t:'Matematika Dasar', c:'Matematika', d:'Ringkasan bilangan, aljabar, dan latihan soal bertahap.', e:'\uD83D\uDCD0', a:'#e00534', b:'#7a0020'},
    {t:'Dasar Sains', c:'Sains', d:'Konsep fisika dan kimia sehari-hari dengan contoh mudah.', e:'\uD83E\uDDEA', a:'#ff6b35', b:'#8c1d2f'},
    {t:'Bahasa Inggris', c:'Bahasa', d:'Grammar, vocabulary, dan percakapan praktis untuk pemula.', e:'\uD83D\uDCDA', a:'#d90429', b:'#2b0a12'},
    {t:'Pemrograman Web', c:'Teknologi', d:'Mulai dari HTML, CSS, sampai membuat halaman pertama.', e:'\uD83D\uDCBB', a:'#9d0208', b:'#370617'},
    {t:'Geografi Indonesia', c:'Sosial', d:'Peta, wilayah, dan potensi daerah di nusantara.', e:'\uD83C\uDF0D', a:'#e5383b', b:'#660708'},
    {t:'Seni dan Desain', c:'Kreatif', d:'Dasar warna, komposisi, dan tips desain sederhana.', e:'\uD83C\uDFA8', a:'#c1121f', b:'#1a0a10'},
    {t:'Simulasi CPNS', c:'CPNS', d:'Latihan SKD lengkap dengan timer, skor otomatis, dan pembahasan tiap soal.', e:'\uD83C\uDFAF', a:'#f2b705', b:'#7a0020'}
  ];

  // ---- Kartu nyata ----
  function wire(card){
    card.addEventListener('click', function(e){
      if (e.target.closest('.card-button')) return;
      if (window.matchMedia('(hover: none)').matches) card.classList.toggle('active');
      else if (card.getAttribute('data-url') && card.getAttribute('data-url') !== '#') location.href = card.getAttribute('data-url');
    });
  }
  document.querySelectorAll('.card').forEach(function(card){
    var p = card.querySelector('[data-snippet]');
    var txt = (p.textContent || '').trim();
    var m = txt.match(/^(Rp\.?\s?[\d.,]+|\$\s?[\d.,]+)/i);
    var price = m ? m[1] : '';
    var desc = m ? txt.slice(m[0].length).replace(/^[\s\-:|]+/, '') : txt;
    var lbl = card.querySelector('.lbl');
    p.textContent = price || (lbl ? lbl.textContent : 'Materi');
    card.querySelector('.card-description').textContent = desc;
    wire(card);
  });

  var g = document.querySelector('.grid');
  var hero = document.getElementById('hero-art');
  var hasPosts = g && g.querySelector('.card');

  // Postingan tanpa gambar otomatis dapat ikon sesuai kategori
  if (hasPosts) {
    g.querySelectorAll('.card').forEach(function(card){
      var img = card.querySelector('.card-img img');
      if (img && (img.getAttribute('src') || '').indexOf('%23971C35') > -1) {
        var lbl = (card.querySelector('.lbl') || {}).textContent;
        var title = (card.querySelector('.card-title') || {}).textContent || '';
        var h = 0; for (var k = 0; k < title.length; k++) h += title.charCodeAt(k);
        var x = demo.filter(function(d){ return d.c === lbl; })[0] || demo[h % demo.length];
        img.src = art(x.e, x.a, x.b);
      }
    });
  } else if (g) {
    g.style.padding = '20px 0';
    g.innerHTML = '<p class="kosong">Belum ada materi. Tambahkan lewat Postingan baru di Blogger.</p>';
  }

  // Kartu kategori (permanen di beranda), klik membuka daftar materi per label
  if (g && hero) {
    var cats = '';
    demo.forEach(function(x){
      var url = '/search/label/' + encodeURIComponent(x.c);
      cats += '<div class="card" data-url="' + url + '"><div class="card-img"><img alt="" src="' + art(x.e, x.a, x.b) + '"/></div>'
           + '<div class="card-data"><p class="card-title">' + x.t + '</p><p class="card-price">Kategori</p>'
           + '<p class="card-description">' + x.d + '</p><a class="card-button" href="' + url + '">LIHAT MATERI</a></div></div>';
    });
    var sec = document.createElement('section');
    sec.innerHTML = '<h2 class="sec-title">Jelajahi Kategori</h2><div class="grid cat-grid">' + cats + '</div>';
    var pager = document.querySelector('.pager');
    (pager || g).insertAdjacentElement('afterend', sec);
    sec.querySelectorAll('.card').forEach(wire);
  }

  // Hero: gambar melayang
  if (hero) {
    var imgs = [];
    var real = hasPosts ? document.querySelectorAll('.grid .card-img img') : [];
    if (real.length >= 3) { for (var i = 0; i < 3; i++) imgs.push(real[i].src); }
    else { for (var j = 0; j < 3; j++) imgs.push(art(demo[j].e, demo[j].a, demo[j].b)); }
    hero.innerHTML = imgs.map(function(s){ return '<img alt="" src="' + s + '"/>'; }).join('');
  }

  // ---- WhatsApp ----
  var wa = document.getElementById('wa-btn');
  if (wa) {
    var t = (document.querySelector('.post-page h1') || {}).textContent || '';
    wa.href = 'https://wa.me/' + WA + '?text=' + encodeURIComponent('Halo, saya mau tanya soal materi: ' + t.trim());
  }
  var ws = document.getElementById('wa-side');
  if (ws) ws.href = 'https://wa.me/' + WA + '?text=' + encodeURIComponent('Halo, saya mau tanya soal materi.');
})();
//
